    fun dueLabel(loan: Loan, today: LocalDate): String {
        val days = today.daysUntil(loan.dueOn)
        return when {
            days < 0 -> "Overdue by ${-days} days"
            days == 0 -> "Due today"
            else -> "Due in $days days"
        }
    }

    fun isOverdue(loan: Loan, today: LocalDate): Boolean = loan.dueOn < today

    fun renew(loan: Loan, until: LocalDate) {
        database.execute(
            "UPDATE loans SET due_on = ? WHERE id = ?",
            until.toString(),
            loan.id,
        )
    }
}

