internal class RenewLoan(
    private val loans: LoanRepository,
    private val borrowers: BorrowerRepository,
    private val eligibility: RenewalEligibility,
) {
    suspend operator fun invoke(loanId: LoanId): RenewalOutcome {
        val loan = loans.byId(loanId) ?: return RenewalOutcome.NoSuchLoan
        val borrower = borrowers.standing(loan.borrowerId)

        return when (val decision = eligibility.decide(loan, borrower)) {
            is RenewalDecision.Refused -> RenewalOutcome.Refused(decision.reason)
            is RenewalDecision.Allowed -> {
                loans.renew(loanId, until = decision.newDueOn)
                RenewalOutcome.Renewed(decision.newDueOn)
            }
        }
    }
}

