fun onAction(action: PracticeAction) {
    when (action) {
        is SelectTopic -> {
            _uiState.update { it.copy(topic = action.topic) }
            recheckStartEnabled()
        }
        is SelectDifficulty -> {
            _uiState.update { it.copy(difficulty = action.difficulty) }
            recheckStartEnabled()
        }
        Retry -> load()
    }
}

