inline fun visitIds(ids: List<String>, action: (String) -> Unit) {
    for (id in ids) action(id)
}

fun firstLocalId(ids: List<String>): String? {
    visitIds(ids) { id ->
        if (id.startsWith("local:")) return id
    }
    return null
}

fun reportRemoteIds(ids: List<String>): List<String> {
    val reported = mutableListOf<String>()
    visitIds(ids) { id ->
        if (id.startsWith("local:")) return@visitIds
        reported.add(id)
    }
    return reported
}

