inline fun prepareThenRemember(
    callbacks: CompletionCallbacks,
    crossinline prepare: () -> Unit,
    noinline onComplete: () -> Unit,
): Runnable {
    callbacks.onComplete = onComplete
    return Runnable { prepare() }
}

fun prepareDownload(callbacks: CompletionCallbacks): Runnable {
    return prepareThenRemember(
        callbacks,
        prepare = { println("Prepare download") },
        onComplete = { println("Download finished") },
    )
}

