import kotlinx.coroutines.launch

fun observeForecast(
    owner: LifecycleOwner,
    title: TextView,
    warning: TextView,
    conditions: Flow<String>,
    warnings: Flow<String>,
) {
    owner.lifecycleScope.launch {
        owner.repeatOnLifecycle(Lifecycle.State.STARTED) {
            launch {
                conditions.collect { title.text = it }
            }
            launch {
                warnings.collect { warning.text = it }
            }
        }
    }
}

