@Composable
fun OrderPreviewOverlay(
    visible: Boolean,
    onDismiss: () -> Unit,
    underlyingContent: @Composable () -> Unit,
) {
    var previewProgress by remember { mutableFloatStateOf(0f) }
    PredictiveBackHandler(enabled = visible) { progress ->
        try {
            progress.collect { event ->
                previewProgress = event.progress.coerceIn(0f, 1f)
            }
            onDismiss()
        } catch (cancelled: CancellationException) {
            throw cancelled
        } finally {
            previewProgress = 0f
        }
    }
    Box {
        underlyingContent()
        if (visible) {
            Box(Modifier.graphicsLayer {
                alpha = 1f - previewProgress
                scaleX = 1f - 0.05f * previewProgress
                scaleY = 1f - 0.05f * previewProgress
            }) {
                Text("Order preview")
            }
        }
    }
}

